[TFMDescription("Expression to find the default receipt location of a certain item. Takes ItemId, and InventLocationid as Paramters")]
class MobExpressionsDefaultReceiptLocation extends TFMExpressions
{

}

Method.Source:
public str processExpressionValue(str _value, InventLocationid _inventLocationId = '')
{
    str ret;
    InventDim inventDimFinalWhs;
    inventDimFinalWhs.clear();
    inventDimFinalWhs.InventLocationId = _inventLocationId;//MobDocWarehouseContentOffline::getFinalWarehouse().InventLocationId;
    inventDimFinalWhs = InventDim::findOrCreate(inventDimFinalWhs);
    ret = inventDimFinalWhs.inventDimId ? InventItemLocation::findFixedWarehouse(_value,inventDimFinalWhs.inventDimId).WMSLocationIdDefaultReceipt : '';

    return ret;
}
